style.css:
@-moz-document url-prefix("https://ppomppu.co.kr"), url-prefix("https://www.ppomppu.co.kr") {
/* Ppomppu is an old-school, table-heavy legacy site: no CSS custom properties,
     colours are hardcoded per element (white wrappers over a transparent <body>,
     grey table rows/cells, literal hex borders). The retheme paints a dark base
     on the root, then overrides every light wrapper / row / cell / input / menu
     to a dark equivalent, softens the bright gridlines, and remaps the dark body
     text to a light tone. Brand + semantic colours (the hot-deal highlight, the
     blue recommend CTA, price text, the red "report" and orange "other-opinion"
     accents, link blue) are preserved — only their tone is refined to sit well
     on the dark canvas. */

  :root {
    color-scheme: dark;
  }

  /* ---- Base ---------------------------------------------------------------- */
  html {
    background-color: #14181d !important;
  }

  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Generic text default — the legacy markup hardcodes near-black / dark-grey
     text colours on countless nodes (logo text, list cells, post body, comment
     notices, home tabs). They read fine on the original white but go
     dark-on-dark here, so force the common body text to a readable light tone.
     Semantic colours (blue links, hot/price/report accents) are re-asserted
     after this with their own rules. */
  body,
  td, th, p, li, dt, dd, span, div, a, font, label, b, strong, em, small, em,
  time, nobr, h1, h2, h3, h4, h5, h6 {
    color: #c4cdd6 !important;
  }

  /* ---- Soften light borders & gridlines ------------------------------------ */
  * {
    border-color: #2d333b !important;
  }

  /* ---- Page wrappers / content shells -------------------------------------- */
  .wrapper,
  .container,
  .contents,
  #contents_view,
  .contents_header,
  .contents_header.abs {
    background-color: #14181d !important;
  }

  /* ---- Header / search bar ------------------------------------------------- */
  .header,
  #gnb,
  .top_header {
    background-color: #0d1117 !important;
  }

  .input-search,
  .search_box,
  .search_wrap {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Search-box "인기검색어" (hot-keyword) flyout — opened by the ▼ toggle beside
     the board/forum search field (#subpage-hot-keyword). The site renders the
     ranked-keyword panel (.hot-keyword-wrapper) on a hardcoded pure-white bg, so
     the flyout ships as a bright white popover and the light keyword labels land
     light-on-white = washed out. Closed by default, so the white-surface scan
     never sees it. Repaint to the elevated dark surface; the ranked-number
     badges + link labels read fine on dark. */
  .hot-keyword-wrapper,
  #subpage-hot-keyword .hot-keyword-wrapper {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ---- Nav / tab strips ---------------------------------------------------- */
  .nav,
  .post_nav,
  ul.tabs,
  .tabs,
  .cate_view {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Board-list category filter chips (#navlist in .navcontainer): the site
     renders each category as a near-white grey pill, so the light chip labels
     wash out (light-on-light). Repaint to dark elevated pills; the selected
     chip (a#current) reads a touch brighter to mark the active filter. */
  .navcontainer #navlist a,
  #navlist a {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .navcontainer #navlist a#current,
  #navlist a#current {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* The "핫/인기" chip marks its 인기 segment with a pure-blue <mark>; on the dark
     pill that blue is too dark — lift to the theme accent and clear the default
     yellow mark highlight. */
  #navlist a mark {
    color: #5fb0e6 !important;
    background-color: transparent !important;
  }

  /* Home 이슈 news-keyword chips (li.cate-keyword > a — the tappable person /
     topic tags under the issue-news column, e.g. "린" / "박소영"): the site
     hardcodes a near-white #eef1f8 pill and the label inherits the light body
     text, so each chip washes out light-on-light. Repaint to a dark elevated
     pill with a readable light label. (Short pill, below the white-surface
     scan's size threshold.) */
  li.cate-keyword a {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .cate_view {
    color: #c4cdd6 !important;
  }

  /* Board-list / forum title bar (.bbs_title — "<board> 입니다." with the
     right-side related-board links). The site paints the bar with a near-white
     linear-gradient as a background-IMAGE (its background-color is transparent),
     so the strip ships bright on dark and is invisible to a background-color
     scan. Repaint to the elevated dark surface and clear the gradient; the board
     title + links inherit the light body text. The small arrow icon on .bname is
     a child background-image and is left intact. */
  .bbs_title {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }

  /* Error / notice page card (.error2 — the "알립니다" alert box shown on invalid
     board ids, deleted posts, access-denied redirects, etc.). The site frames
     the card with a white JPG (line_02.jpg) set as a background-IMAGE while the
     element's background-color is transparent, so the box ships bright white and
     the muted-grey notice text lands light-on-white = washed out. Both the
     bg-color scan and the audit-blind walk miss it (image, not color). Clear the
     white frame and paint the elevated dark surface; the notice text reads. */
  .error2 {
    background-image: none !important;
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Forum-hub page (recent_forum_article.php — the "포럼" aggregation view): the
     "포럼통합검색" search bar / ranking-sort strip at the top of the forum-ranking
     box (.forum_gategory_top) hardcodes a near-white #f6f6f6 bg, so it ships as a
     bright bar across the dark ranking grid. Repaint to the elevated dark surface;
     the 랭킹순/추천순/가나다순 labels inherit the light body text. */
  .forum_gategory_top {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Forum-ranking numeral badges (span.ranking_num — the "1"/"2"/… rank chips
     beside each forum name in the ranking grid): the site hardcodes a light-grey
     #f7f7f7 pill, so every rank badge shows a bright square on the dark grid.
     Repaint to a dark elevated pill with a readable light numeral. (22×20 — below
     the white-surface scan's size threshold.) */
  span.ranking_num,
  .ranking_num {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* ---- Login / utility boxes ----------------------------------------------- */
  .login_box,
  .ppomCou,
  .agent,
  .together_goods,
  .addFile,
  .scrap_bx {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Login social-login section (.sc1): the "SNS 계정으로 로그인" label rides a
     white strip (.sns-title .txt) and the bottom "회원 전환 / 되돌아가기" pill
     (.backs) is a near-white grey — both leave the light body text unreadable.
     Repaint to dark so the labels read; SNS brand icons are left untouched. */
  .sc1 .sns-title .txt,
  .sc1 .backs {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* Home login-box CTA (img btn_login.jpg inside .login_box, shown logged-out):
     the site's login button is a 277×42 raster JPG — the colourful PPOMPPU logo
     + grey "로그인" baked onto a WHITE background — so it ships as a bright white
     pill on the dark home panel (a raster fill the bg-color scan can't see, and
     a JPG has no transparency to paint through). Invert its lightness so the
     white ground goes dark while hue-rotate keeps the rainbow logo hues intact
     and the grey label readable. Scoped to the btn_login src so nothing else is
     touched. */
  .login_box img[src*="btn_login"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Standalone-template PPOMPPU logo (img src=ppomppu.gif): the minimal legacy
     templates (404 / error / access-denied pages under div#wrap) use the GIF
     logo — the colourful "PPOMPPU" wordmark baked onto a WHITE background — so it
     ships as a bright white box on the dark error card (a raster fill the
     bg-color scan can't see; the img's own bg is transparent). The main site
     header uses a transparent logo.png and is untouched. Invert the lightness so
     the white ground goes dark while hue-rotate keeps the neon wordmark hues.
     Scoped to the ppomppu.gif src so nothing else is affected. */
  img[src*="ppomppu.gif"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Compact-header login pill (a.loginsmbtn inside .smloginbtnbox — the small
     "로그인" button shown logged-out on board / forum / post / search headers):
     the site hardcodes a pure-white bg, and our light body text colour then
     lands light-on-white = washed out. Repaint to a dark elevated pill with a
     bright readable label. (37×20 — below the white-surface scan's size filter.) */
  a.loginsmbtn,
  .smloginbtnbox a {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ---- Home post panels ---------------------------------------------------- */
  .post_wrap,
  .post_wrap.real_time,
  .post_wrap.best_time,
  .bx-clone,
  .ad-banner,
  .middle-banner,
  li.img_title,
  .ranking_wrap,
  .real_hot_wrap,
  .main_list,
  .main_market {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Home real-time hot list (white <ul>/<li> sliders) */
  .post_wrap ul,
  .post_wrap li,
  .real_time ul,
  .real_time li,
  .js-real_hot ul,
  .js-real_hot li,
  .js-real_ppom ul,
  .js-real_ppom li,
  .main_list ul,
  .main_list li {
    background-color: transparent !important;
  }

  /* ---- Board list table ---------------------------------------------------- */
  #revolution_main_table,
  table.bbs_new1,
  .board_list,
  .info_bg {
    background-color: #14181d !important;
  }

  /* List header row */
  tr.title_bg,
  tr.title_bg td,
  .list_title,
  thead tr,
  thead th {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* Notice rows (lightly tinted) */
  tr.baseNotice,
  tr.baseNotice td,
  #headNotice,
  #headNotice td {
    background-color: #1b2026 !important;
  }

  /* Standard deal rows (alternating light tones -> dark) */
  tr.baseList,
  tr.baseList td,
  tr.bbs_new1,
  tr.list1,
  tr.list0 {
    background-color: #161b22 !important;
  }

  tr.baseList:hover,
  tr.baseList:hover td {
    background-color: #1f252d !important;
  }

  /* Hot-deal highlighted row — keep the warm "hot" tint, refined for dark */
  tr.hotpop_bg_color,
  tr.hotpop_bg_color td,
  .hotpop_bg_color {
    background-color: #2a2017 !important;
  }

  /* Board-list shopping-forum promo banner (.bridge_area) — site hardcodes a
     near-white bg with dark text; repaint dark so the light text inherits. */
  .bridge_area,
  .bridge_area p {
    background-color: #1c2128 !important;
  }

  /* Search-results "파워링크" sponsored-link block — rendered in the page DOM
     (not a cross-origin ad iframe) with a hardcoded near-white container; repaint
     to the elevated dark surface so the link/description text reads on dark. */
  #div_new_power_link,
  #powerlinknew {
    background-color: #1c2128 !important;
  }

  /* The block's link titles are a deep ad-blue (#071ac8) tuned for white — too
     dark on the repainted surface; lift to the theme accent so they read. */
  #powerlinknew a.title,
  #div_new_power_link a.title {
    color: #5fb0e6 !important;
    -webkit-text-fill-color: #5fb0e6 !important;
  }

  /* ---- Comments ------------------------------------------------------------ */
  #quote,
  .comment_wrapper,
  .comment_template_depth1,
  .comment_template_depth2,
  .comment_view,
  .cmt_list,
  .han02 {
    background-color: transparent !important;
  }

  .comment_wrapper {
    border-color: #2d333b !important;
  }

  /* Nested reply rows get a faint elevation */
  .comment_template_depth2,
  .comment_template_depth3 {
    background-color: #161b22 !important;
  }

  /* Post-author reply highlight: the site paints the author's comment content
     cell a near-white grey (depth2_vote) to flag it as the writer's reply. The
     dark depth wrapper above doesn't cover this inner cell, so it stays bright.
     Repaint to a subtly elevated dark surface so the author signal survives. */
  .comment_template_depth2_vote {
    background-color: #1c2128 !important;
  }

  /* Comment tooltip / balloon (was pale blue) */
  .ppomppu_cmt_balloon,
  #ppomppu_cmt_tooltip {
    background-color: #1c2733 !important;
    border-color: #2d3b4d !important;
    color: #c4cdd6 !important;
  }

  /* Comment recommend / not-recommend count boxes (span.cmd_box wrapping the
     up/down icons + count): the site hardcodes a pure-white bg, so each comment
     shows a bright white pill on the dark thread. Repaint to a dark elevated
     pill; the grey icons + light count read fine. (Small box, missed by the
     white-surface scan's size filter.) */
  .cmd_box {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* Post action buttons (질렀어요 / 신고 — span.buttonBox-impulse / -report):
     the 질렀어요 pill hardcodes a near-white #f8f8f8 bg. Repaint the whole
     buttonBox family to a dark elevated pill so both buttons match; the impulse
     count + report-red icon stay readable. */
  [class^="buttonBox-"] {
    background-color: #21262d !important;
  }

  /* Default profile avatar (img.over_hide src=no_face.jpg): the site's
     placeholder avatar is a 100×100 white JPG with a faint watermark, so every
     comment from a user without a custom photo — and the post author thumb —
     renders a bright white square on the dark thread. Darken the placeholder to
     a neutral dark tile. Scoped to the no_face src so real uploaded avatars and
     deal photos are untouched. (Below the white-surface scan's size threshold,
     and a raster fill the bg-color walk can't see.) */
  img[src*="no_face"] {
    filter: brightness(0.2) !important;
  }

  /* Same default-avatar placeholder, but applied as an inline CSS
     background-image instead of an <img> — e.g. the post-author thumb
     span.topTitle-profile (a 100×100 near-white watermark tile). The img rule
     above can't reach a CSS background, and the span's own bg-color is near-white,
     so authors without a custom photo show a bright white square. Scoped to the
     no_face placeholder so real uploaded avatars are untouched; clear the
     watermark and paint a neutral dark tile. */
  [style*="no_face"] {
    background-color: #161b22 !important;
    background-image: none !important;
  }

  /* ---- Generic light cell backgrounds (catch-all for table cells) ---------- */
  td[bgcolor],
  th[bgcolor],
  tr[bgcolor],
  table[bgcolor] {
    background-color: #161b22 !important;
  }

  /* Inline light backgrounds the legacy markup hardcodes (white/grey cells,
     quote-link chips). Catch the common literal values. */
  [bgcolor="#ffffff"],
  [bgcolor="#FFFFFF"],
  [bgcolor="white"],
  [bgcolor="#f5f5f5"],
  [bgcolor="#eeeeee"],
  [bgcolor="#fafafa"],
  [style*="background:#fff"],
  [style*="background-color:#fff"],
  [style*="background: #fff"] {
    background-color: #161b22 !important;
  }

  /* Pagination / quoted-link chips that used a light-grey bg */
  .nav a,
  .page a,
  .paging a,
  a[style*="background"] {
    background-color: #21262d !important;
  }

  /* List pagination: inactive page links (a.num) sit transparent on dark and
     read fine, but the ACTIVE page (a.num.on) hardcodes a near-white cream bg
     (#fff6f4) with a muted-grey numeral — light-on-light. Repaint to a dark
     elevated pill with a bright numeral so the active page reads. (Short pill,
     missed by the white-surface scan's size filter.) */
  a.num.on,
  .paging a.on,
  .page a.on {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* List comment-count badge (span.baseList-c next to deal / board titles): the
     site hardcodes a light-grey #f0f0f0 pill and the numeral inherits the light
     body text, so the count washes out light-on-light. Repaint to a dark
     elevated pill with a readable light numeral. (Small badge, below the
     white-surface scan's size threshold.) */
  span.baseList-c,
  .baseList-c {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Post-title comment-count badge (span#comment inside #topTitle h1 — the
     bracketed reply count shown beside the deal title on a post page): the site
     hardcodes a light-grey #f0f0f0 pill and the numeral inherits the light body
     text, so the count washes out light-on-light. Repaint to a dark elevated
     pill with a readable light numeral. (Small badge, below the white-surface
     scan's size threshold.) */
  #topTitle #comment {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Comment "load more" button + similar grey action chips */
  .cmt-more-btn-pc,
  .new-cmt-btn-pc,
  .cmt-more-btn-pc a,
  .cmt_more,
  .more_btn {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* Home image sliders (bxSlider) + image-forum tiles + box-out dropdown tiles */
  .bx-viewport,
  .bx-viewport ul,
  .bx-clone,
  .img_forum,
  .img_forum ul,
  .img_forum li,
  .imgbox,
  .imgbox li,
  li.img_title {
    background-color: #1c2128 !important;
  }

  /* Gallery boards (free_gallery / star / sketch_gallery …): each thumbnail card
     is a .gallery_list wrapper whose bg the site hardcodes a near-white #f7f7f7,
     with the photo in an inner li.gallery_img cell hardcoded pure white. The
     wrapper bg shows as a bright frame AND sits behind the caption row, washing
     the light title/author text light-on-light; the image cell shows white
     letterbox behind non-filling thumbnails. Repaint the card to the elevated
     dark surface and the image cell to the darker base so captions read and
     letterboxing goes dark. The <img> thumbnails sit on top untouched. */
  .gallery_list {
    background-color: #1c2128 !important;
  }

  li.gallery_img,
  .gallery_img {
    background-color: #161b22 !important;
  }

  /* Home "community / 구매후기" review thumbnails (span.review-thumb): the photo
     is set as a background-image over a hardcoded near-white #f1f1f1 bg-color, so
     the white shows as a frame / load-flash behind the thumb. Darken the
     container bg-color only — the photo background-image is left intact. */
  .review-thumb {
    background-color: #161b22 !important;
  }

  /* Home 뽐뿌쿠폰 preview thumbnails (span.link_view inside .ppomCou — the coupon
     graphics in the right consult aside): each thumb is a photo set as a
     background-image over a hardcoded pure-white bg-color, so the white shows as
     a frame / load-flash behind coupon art that doesn't fill the tile. Darken
     the container bg-color only; the coupon background-image is left intact. */
  .link_view {
    background-color: #161b22 !important;
  }

  /* News-hub "포토뉴스" photo thumbnails (span.ibox inside div.new_imgboard on
     recent_main_article.php?type=news): each thumb is a photo set as a
     background-image over a hardcoded near-white #f1f1f1 bg-color, so the white
     shows as a frame / load-flash behind photos that don't fill the tile. Darken
     the container bg-color only; the photo background-image is left intact. */
  .new_imgboard .ibox,
  span.ibox {
    background-color: #161b22 !important;
  }

  /* News-hub right column (div#news_right_area.right_newSub on
     recent_main_article.php?type=news — the ranked-news list + 포토뉴스 photo
     column beside the main feed): the site hardcodes a pure-white bg on the
     column wrapper while its list/thumbnail children sit transparent, so the
     white shows through behind the items and the light body text (news titles,
     photo captions) lands light-on-white = washed out. The bg-color scan only
     catches it once the column's ajax content settles. Repaint to the elevated
     dark surface so the titles + captions read. */
  #news_right_area,
  .right_newSub {
    background-color: #1c2128 !important;
  }

  /* Home 상담실 후기 (consultation-review) company label (span.review-company next
     to each review title): the site hardcodes a light-grey #f0f0f0 pill and the
     label inherits the light body text, so the company name washes out
     light-on-light. Repaint to a dark elevated pill with a readable light label.
     (Small pill, below the white-surface scan's size threshold.) */
  .review-company {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* ---- Forms / inputs ------------------------------------------------------ */
  input[type="text"],
  input[type="password"],
  input[type="search"],
  input[type="email"],
  input[type="number"],
  input[type="url"],
  input:not([type]),
  textarea,
  select,
  #keyword {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  input::placeholder,
  textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  /* Rich comment editor iframe area background (CHEditor) */
  .cheditor-editarea {
    background-color: #0d1117 !important;
  }

  /* CHEditor drag-to-resize bar below the edit area — site hardcodes a light
     #eee strip (with a grip-dot background-image), so it ships as a bright bar
     across the comment editor. Repaint to the elevated dark surface; the grip
     texture reads fine on dark. */
  .cheditor-resizebar {
    background-color: #21262d !important;
    background-image: none !important;
  }

  /* CHEditor toolbar tabs (에디터 / HTML편집 / 미리보기) — hardcoded light-grey
     pills; repaint dark with a readable light label. */
  [class^="cheditor-tab"] {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* ---- Buttons / pop menus ------------------------------------------------- */
  button,
  .btn,
  .btn-reset,
  input[type="button"],
  input[type="submit"] {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Active/selected segmented toggle (e.g. article/comment switch on home) */
  .btn-reset.on,
  #user_box_article.on,
  button.on {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* Home consult/inquiry CTA (.consult-btn) — site hardcodes a pure-white pill;
     repaint to an elevated dark surface with a readable light label. */
  .consult-btn-wrap,
  .consult-btn {
    background-color: #21262d !important;
  }

  .consult-btn {
    color: #e6edf3 !important;
  }

  /* Floating pop menus / dropdowns — keep opaque so content doesn't bleed */
  .list_pop_menu01,
  .user_box_out,
  [id^="user_box_content"],
  .layer_pop,
  .pop_menu {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* ---- Headings & links ---------------------------------------------------- */
  h1, h2, h3, h4, h5, h6,
  .title, .subject, .topTitle {
    color: #e6edf3 !important;
  }

  a {
    color: #c4cdd6;
  }

  a:hover {
    color: #9bd4ff;
  }

  /* Subject / deal-title links on the list */
  .baseList a,
  .subject a,
  td.han a {
    color: #e6edf3 !important;
  }

  .baseList a:hover,
  .subject a:hover {
    color: #9bd4ff !important;
  }

  /* ---- Muted metadata (dates, view counts, author, separators) ------------- */
  /* The site colours these with dark greys (rgb 96/117/132 etc.) that go
     dark-on-dark; lift them all to a legible muted grey. */
  .list_vspac,
  .info,
  .date,
  .hit,
  .writer,
  .author,
  .reg_date,
  .num,
  .baseList font[color="#999999"],
  .baseList font[color="#888888"],
  .baseList font[color="#777777"],
  font[color="#666666"],
  font[color="#999999"],
  font[color="#888888"] {
    color: #9aa4ae !important;
  }

  /* ---- Semantic / brand colours (preserved, tone-refined for dark) --------- */

  /* Price text — was near-black; make it bright + readable, keep it neutral */
  .bx_price,
  .price {
    color: #e6edf3 !important;
  }

  /* Recommend (추천) CTA — keep the brand blue, refine for dark */
  .recommend-up,
  .recommend-up:hover {
    background-color: #2f6db0 !important;
    color: #ffffff !important;
    border-color: #2f6db0 !important;
  }

  /* Down-vote / "다른의견" CTA (.recommend-down) — the site renders this as a
     pure-white circle paired with the blue recommend button; our light label
     then lands light-on-white = washed out. Repaint to a dark elevated circle
     with a readable light label so it sits opposite the blue recommend button;
     the grey thumb icon reads fine on dark. */
  .recommend-down,
  .recommend-down:hover {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .recommendArea,
  .topTitle-rec {
    color: #c4cdd6 !important;
  }

  /* Link blue used for in-content links / counts / comment counts / tabs
     (site uses several near-#1264b1 / #0267cf blues that sit a touch dark on
     this canvas) — brighten to the theme accent so they read clearly. */
  a[href*="copy"],
  .link_blue,
  .comment-count,
  .cnt,
  .comment_count,
  .baseList-head,
  .subject_preface,
  li.on,
  font[color="#1970b3"],
  font[color="#0068c0"],
  font[color="#1e4780"],
  font[color="#0267cf"],
  font[color="#1264b1"],
  font[color="blue"] {
    color: #5fb0e6 !important;
  }

  /* "Report" red (신고) — refine the raw red so it isn't garish on dark */
  font[color="#ff0000"],
  font[color="red"],
  .report,
  .txt_red,
  .red {
    color: #ff7b72 !important;
  }

  /* "Other opinion" orange (다른의견) — refined warm accent */
  font[color="#ff5a00"],
  .txt_orange,
  .orange {
    color: #f0883e !important;
  }

  /* ---- Misc light spans / chips -------------------------------------------- */
  /* Comment sort toggle (최신순 / 작성순): the SELECTED pill is span.on, the
     UNSELECTED one is a plain .myComment > span whose bg the site hardcodes to a
     near-white grey. Style both states to a dark elevated pill with a readable
     light label so neither washes out. */
  .bx_view,
  span.on,
  .myComment > span {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Selected sort pill reads a touch brighter to mark the active state */
  .myComment > span.on {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ---- Images: avoid washed-out look on pure-dark, leave content alone ----- */
  /* (no filter on content images — deal photos must stay accurate) */

  /* ---- Scrollbar ----------------------------------------------------------- */
  ::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }
  ::-webkit-scrollbar-track {
    background: #14181d;
  }
  ::-webkit-scrollbar-thumb {
    background: #2d333b;
    border-radius: 6px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #3a414b;
  }
}
